// 1. Get the source of truth and the LLM output
const resume = $('My Resume').first().json.resume.toLowerCase();
const out = $input.first().json.output;
const bullets = (out.bullets || []).map(b => b.replace(/[\u2010-\u2015\u2212]/g, '-').replace(/[\u00a0\u202f]/g, ' '));
const skills = out.matched_skills || [];
const text = [...bullets, ...skills].join(' \n ').toLowerCase();

// 2. Tech words to watch for
const techWords = ['python','sql','java','javascript','typescript','react','node.js','django','flask','fastapi',
  'langchain','llamaindex','rag','vector database','pinecone','chroma','faiss','openai','groq','whisper',
  'pydantic','sqlite','postgresql','mysql','mongodb','streamlit','n8n','zapier','docker','kubernetes',
  'aws','azure','gcp','pytorch','tensorflow','scikit-learn','pandas','numpy','spark','airflow',
  'hugging face','fine-tuning','.net','power bi','tableau','ci/cd'];

const flags = [];

// 3. Flag any tech word that is in the output but NOT in the resume
for (const w of techWords) {
  const safe = w.replace(/[.*+?^${}()|[\]\\\/]/g, '\\$&');
  const re = new RegExp('(?<![a-z0-9])' + safe + '(?![a-z0-9])', 'i');
  if (re.test(text) && !re.test(resume)) flags.push('New tool: ' + w);
}

// 4. Flag any number that is not in the resume
for (const n of text.match(/\d+(\.\d+)?%?/g) || []) {
  if (!resume.includes(n)) flags.push('New number: ' + n);
}
// Novelty check + auto-repair: if a bullet adds too many new words, use the original bullet instead
const resumeRaw = $('My Resume').first().json.resume;
const originals = resumeRaw.split('\n').filter(l => l.trim().startsWith('- ')).map(l => l.trim().slice(2));
const resumeWords = new Set(resume.match(/[a-z][a-z-]{3,}/g));
bullets.forEach((b, i) => {
  const words = (b.toLowerCase().match(/[a-z][a-z-]{3,}/g) || []);
  const newWords = [...new Set(words.filter(w => !resumeWords.has(w)))];
  if (newWords.length > 3 && originals[i]) {
    flags.push('Bullet ' + (i + 1) + ' reverted (added: ' + newWords.join(', ') + ')');
    bullets[i] = originals[i];
  }
});
if (bullets.length !== 13) flags.push('Expected 13 bullets, got ' + bullets.length);
return [{ json: { bullets, matched_skills: skills, flags: [...new Set(flags)], passed: flags.length === 0 } }];

