const resume = $('My Resume').first().json.resume.toLowerCase();
const out = $input.first().json.output;
const clean = s => (s || '').replace(/[\u2010-\u2015\u2212]/g, '-').replace(/[\u00a0\u202f]/g, ' ');
const letter = clean(out.cover_letter);
const dm = clean(out.dm);
const text = (letter + ' \n ' + dm).toLowerCase();

const techWords = ['react','next.js','node.js','express','mongodb','mysql','typescript','docker','kubernetes',
  'aws','azure','gcp','langchain','rag','pytorch','fastapi','django','flask','optimization','end-to-end',
  'full-stack','frontend','ai-assisted coding','user-centric'];
const cliches = ['passion','passionate','excited','eager','thrilled'];

const flags = [];
for (const w of techWords) {
  const safe = w.replace(/[.*+?^${}()|[\]\\\/]/g, '\\$&');
  const re = new RegExp('(?<![a-z0-9])' + safe + '(?![a-z0-9])', 'i');
  if (re.test(text) && !re.test(resume)) flags.push('Not in resume: ' + w);
}
for (const c of cliches) if (text.includes(c)) flags.push('Cliché: ' + c);

return [{ json: { cover_letter: letter, dm: dm, letter_flags: [...new Set(flags)], letter_passed: flags.length === 0 } }];

